// THE DIRECTORY SEAL (2026-10-27; gc-estate/docs/security-evaluation-2026-10.md). Contact emails are encrypted inside
// the operator directory with a data key that only the directory service can use, so a steward or custodian who
// reads the operations workspace's vault directly (a stewardship grant reads every record) gets ciphertext. Masking,
// recorded reveals and the two-admin export then hold at the data layer, not only in the Admin screens.
//
// The data key is generated by the key service (AKCS envelope purpose `operator-directory`) and only its WRAPPED copy
// is kept, in the directory's own Durable Object storage, which no vault grant reaches. Unwrapping it is an AKCS call,
// audited there; the plaintext key is held in memory for a few minutes and never written anywhere.
//
// Each sealed value is bound to its record (AES-GCM additional data = workspace + record key), so a sealed email
// cannot be copied onto another account's record and read as that account's.

export const SEAL_PURPOSE = 'operator-directory';
const PREFIX = 's1.';
const DEK_TTL_MS = 10 * 60 * 1000;

/** The wrapped data key as the DO stores it. */
export interface StoredDek { wrapped: string; keyId: string; keyVersion: string; createdAt: number }

/** The key service, as the sealer needs it (AKCS envelope keys in production; a fake in tests). */
export interface Envelope {
  generate(aadContext: Record<string, string>): Promise<{ plaintext: Uint8Array; wrapped: Uint8Array; keyId: string; keyVersion: string }>;
  unwrap(dek: { wrapped: Uint8Array; keyId: string; keyVersion: string }, aadContext: Record<string, string>): Promise<Uint8Array>;
}

export interface DekStore { get(): Promise<StoredDek | undefined>; put(d: StoredDek): Promise<void> }

export interface Sealer {
  seal(account: string, email: string): Promise<string>;
  open(account: string, sealed: string): Promise<string>;
}

const b64u = (b: Uint8Array) => btoa(String.fromCharCode(...b)).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
const unb64u = (s: string) => Uint8Array.from(atob(s.replace(/-/g, '+').replace(/_/g, '/') + '==='.slice((s.length + 3) % 4)), (c) => c.charCodeAt(0));
const enc = new TextEncoder();

export const isSealed = (s: unknown): s is string => typeof s === 'string' && s.startsWith(PREFIX);

export function makeSealer(input: { workspace: string; store: DekStore; envelope: Envelope; now?: () => number }): Sealer {
  const workspace = input.workspace.toLowerCase();
  const now = input.now ?? (() => Date.now());
  // The key service binds the data key to this directory: a wrapped key from another workspace does not unwrap here.
  const aadContext = { purpose: SEAL_PURPOSE, workspace, v: '1' };
  let cached: { key: CryptoKey; until: number } | null = null;
  let inflight: Promise<CryptoKey> | null = null;

  const load = async (): Promise<CryptoKey> => {
    let raw: Uint8Array;
    const stored = await input.store.get();
    if (stored) {
      raw = await input.envelope.unwrap({ wrapped: unb64u(stored.wrapped), keyId: stored.keyId, keyVersion: stored.keyVersion }, aadContext);
    } else {
      const g = await input.envelope.generate(aadContext);
      await input.store.put({ wrapped: b64u(g.wrapped), keyId: g.keyId, keyVersion: g.keyVersion, createdAt: now() });
      raw = g.plaintext;
    }
    if (raw.length !== 32) throw new Error('the directory data key is malformed');
    const key = await crypto.subtle.importKey('raw', raw, 'AES-GCM', false, ['encrypt', 'decrypt']);
    raw.fill(0);
    return key;
  };
  const key = async (): Promise<CryptoKey> => {
    if (cached && cached.until > now()) return cached.key;
    // One unwrap (or one generate) at a time: two first uses at once must not mint two data keys.
    inflight ??= load().finally(() => { inflight = null; });
    const k = await inflight;
    cached = { key: k, until: now() + DEK_TTL_MS };
    return k;
  };
  const ad = (account: string) => enc.encode(`${workspace}|contact:${account.toLowerCase()}`);

  return {
    async seal(account, email) {
      const iv = crypto.getRandomValues(new Uint8Array(12));
      const ct = new Uint8Array(await crypto.subtle.encrypt({ name: 'AES-GCM', iv, additionalData: ad(account) }, await key(), enc.encode(email)));
      return `${PREFIX}${b64u(iv)}.${b64u(ct)}`;
    },
    async open(account, sealed) {
      if (!isSealed(sealed)) throw new Error('not a sealed value');
      const [ivB, ctB] = sealed.slice(PREFIX.length).split('.');
      if (!ivB || !ctB) throw new Error('a sealed value is malformed');
      const pt = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: unb64u(ivB), additionalData: ad(account) }, await key(), unb64u(ctB));
      return new TextDecoder().decode(pt);
    },
  };
}
